REPO = Path(__file__).resolve().parents[2]
SPEC = REPO / "files" / "08_ADMIN_CONSOLE_AND_OBSERVABILITY.md"
CATALOG = REPO / "observability" / "metrics_catalog.yaml"
RULES = REPO / "infra" / "observability" / "security-rules.yaml"
