#: INT-563: approvals go through the step-up, the console's own sequence.
STEP_UP = StepUpHarness.build()

T0 = datetime(2026, 9, 27, tzinfo=UTC)
DAY = timedelta(days=1)
HEX64 = re.compile(r"\b[0-9a-f]{64}\b")
CLINICIANS_A = "clinicians:tenant-a"


def _entry(seq: int, at: datetime, actor: str, action: str, ref: str) -> AuditEntry:
    return AuditEntry(
        seq=seq,
        timestamp_utc=at.isoformat(),
        actor=actor,
        action=action,
        resource_ref=ref,
        consent_scope_ref="basis:KVKK-12",
        prev_hash="0" * 64,
        entry_hash="0" * 64,
    )


def _signed(seq: int, at: datetime, section: str) -> AuditEntry:
    return _entry(
        seq, at, "kc-sub-qms-owner", SIGNED_ACTION, signed_resource_ref(section, "a" * 32)
    )


def _users(now: datetime = T0) -> list[DirectoryUser]:
    return FakeKeycloak(now).directory().staff_users()


class Clock:
    def __init__(self, now: datetime) -> None:
        self.now = now

    def __call__(self) -> datetime:
        return self.now


# --- the document ---------------------------------------------------------------------


class TestGeneratedDocument:
    def test_holders_are_exactly_the_staff_role_holders_in_keycloak(self) -> None:
        review = generate_review(_users(), ReviewLedger(clock=Clock(T0)), {}, now=T0)
        subjects = {holder.subject for holder in review.holders}
        assert "kc-sub-no-staff-role" not in subjects
        assert {
            "kc-sub-platform-owner",
            "kc-sub-tenant-admin",
            "kc-sub-compliance-officer",
            "kc-sub-clinician",
            "kc-sub-clinical-lead",
        } <= subjects
        lead = next(h for h in review.holders if h.subject == "kc-sub-clinical-lead")
        assert lead.enabled is False
        assert lead.roles == ("clinical_lead",)

    def test_sections_follow_the_spec_reviewers(self) -> None:
        review = generate_review(_users(), ReviewLedger(clock=Clock(T0)), {}, now=T0)
        by_id = {section.section: section for section in review.sections}
        assert set(by_id) == {SECTION_PLATFORM_OWNER, SECTION_CONSOLE_ROLES, CLINICIANS_A}
        assert by_id[SECTION_PLATFORM_OWNER].holders == ("kc-sub-platform-owner",)
        assert by_id[SECTION_PLATFORM_OWNER].signer_role is AdminRole.COMPLIANCE_OFFICER
        assert by_id[SECTION_PLATFORM_OWNER].countersigner_external is True
        assert by_id[SECTION_CONSOLE_ROLES].signer_role is AdminRole.COMPLIANCE_OFFICER
        assert by_id[SECTION_CONSOLE_ROLES].countersigner_external is False
        assert "kc-sub-platform-owner" not in by_id[SECTION_CONSOLE_ROLES].holders
        assert by_id[CLINICIANS_A].signer_role is AdminRole.TENANT_CLINICAL_RESPONSIBLE
        assert by_id[CLINICIANS_A].signer_tenant == "tenant-a"
        assert "kc-sub-clinician-dormant" in by_id[CLINICIANS_A].holders

    def test_last_login_comes_from_keycloak_and_absence_falls_back_to_creation(self) -> None:
        review = generate_review(_users(), ReviewLedger(clock=Clock(T0)), {}, now=T0)
        holders = {holder.subject: holder for holder in review.holders}
        dormant = holders["kc-sub-clinician-dormant"]
        assert dormant.last_login_at == datetime(2026, 7, 1, 9, tzinfo=UTC)
        assert dormant.days_until_auto_disable < 0
        never = holders["kc-sub-sre-oncall"]
        assert never.last_login_at is None
        assert never.days_since_activity == pytest.approx(
            (T0 - datetime(2026, 6, 1, 10, tzinfo=UTC)) / DAY
        )

    def test_last_console_action_comes_from_the_audit_chain(self) -> None:
        entries = [
            _entry(
                1,
                T0 - 3 * DAY,
                "kc-sub-compliance-officer",
                "admin.whoami.read.success",
                "admin_action:x:y",
            ),
            _entry(
                2,
                T0 - DAY,
                "kc-sub-compliance-officer",
                "admin.actions.read.success",
                "admin_action:x:z",
            ),
            _entry(3, T0 - DAY, "kc-sub-clinician", "api.note.read", "note:1"),
        ]
        actions = last_console_actions(entries)
        assert actions == {"kc-sub-compliance-officer": T0 - DAY}
        review = generate_review(_users(), ReviewLedger(clock=Clock(T0)), actions, now=T0)
        officer = next(h for h in review.holders if h.subject == "kc-sub-compliance-officer")
        assert officer.last_console_action_at == T0 - DAY

    def test_a_login_moves_no_digest_but_a_grant_does(self) -> None:
        users = _users()
        section = [u for u in users if "clinician" in u.realm_roles and u.tenant == "tenant-a"]
        baseline = section_digest(CLINICIANS_A, section)
        relogged = [
            DirectoryUser(**{**vars(u), "last_login_at": T0})
            if u.subject == "kc-sub-clinician"
            else u
            for u in section
        ]
        assert section_digest(CLINICIANS_A, relogged) == baseline
        granted = [
            DirectoryUser(**{**vars(u), "realm_roles": u.realm_roles | {"support"}})
            if u.subject == "kc-sub-clinician"
            else u
            for u in section
        ]
        assert section_digest(CLINICIANS_A, granted) != baseline
        assert len(baseline) == 32 and not HEX64.search(baseline)


# --- the ledger, the clock and the downgrade -----------------------------------------


class TestReadOnlyPastOneHundredDays:
    def test_the_spec_still_states_the_threshold_and_the_two_roles(self) -> None:
        section = SPEC.read_text(encoding="utf-8").split("### 2.7 ", 1)[1].split("\n## ", 1)[0]
        assert (
            "older than 100 days downgrades every `platform_owner` and `tenant_admin` "
            "session to read-only" in section
        )
        assert REVIEW_MAX_AGE_DAYS == 100
        assert READ_ONLY_ROLES == frozenset({AdminRole.PLATFORM_OWNER, AdminRole.TENANT_ADMIN})

    def test_never_reviewed_is_read_only(self) -> None:
        ledger = ReviewLedger(clock=Clock(T0))
        ledger.load([])
        assert ledger.review_age_days() == float("inf")
        assert ledger.read_only_roles() == READ_ONLY_ROLES

    def test_an_unloaded_ledger_is_read_only(self) -> None:
        ledger = ReviewLedger(clock=Clock(T0))
        assert ledger.read_only_roles() == READ_ONLY_ROLES

    def test_one_second_either_side_of_one_hundred_days(self) -> None:
        clock = Clock(T0)
        ledger = ReviewLedger(clock=clock)
        ledger.load([_signed(1, T0, SECTION_PLATFORM_OWNER), _signed(2, T0, SECTION_CONSOLE_ROLES)])
        clock.now = T0 + 100 * DAY - timedelta(seconds=1)
        assert ledger.read_only_roles() == frozenset()
        clock.now = T0 + 100 * DAY + timedelta(seconds=1)
        assert ledger.read_only_roles() == READ_ONLY_ROLES

    def test_the_stalest_console_section_decides(self) -> None:
        clock = Clock(T0 + 50 * DAY)
        ledger = ReviewLedger(clock=clock)
        ledger.load([_signed(1, T0, SECTION_CONSOLE_ROLES)])
        # platform_owner was never countersigned
        assert ledger.read_only_roles() == READ_ONLY_ROLES
        ledger.load(
            [
                _signed(1, T0, SECTION_CONSOLE_ROLES),
                _signed(2, T0 + 40 * DAY, SECTION_PLATFORM_OWNER),
            ]
        )
        assert ledger.review_age_days() == pytest.approx(50.0)
        assert ledger.read_only_roles() == frozenset()

    def test_a_clinician_section_does_not_stand_in_for_the_console_review(self) -> None:
        ledger = ReviewLedger(clock=Clock(T0))
        ledger.load([_signed(1, T0, CLINICIANS_A)])
        assert ledger.read_only_roles() == READ_ONLY_ROLES
        assert ledger.last_signed(CLINICIANS_A) == T0

    def test_a_row_that_does_not_parse_is_not_a_review(self) -> None:
        ledger = ReviewLedger(clock=Clock(T0))
        ledger.load(
            [
                _entry(1, T0, "x", SIGNED_ACTION, "access_review:platform_owner"),
                _entry(2, T0, "x", SIGNED_ACTION, "something_else:console_roles:" + "a" * 32),
                _entry(
                    3,
                    T0,
                    "x",
                    SIGNED_ACTION + ".intent",
                    signed_resource_ref(SECTION_CONSOLE_ROLES, "a" * 32),
                ),
            ]
        )
        assert ledger.read_only_roles() == READ_ONLY_ROLES

    def test_the_age_is_emitted_at_scrape_time(self) -> None:
        clock = Clock(T0)
        ledger = ReviewLedger(clock=clock)
        ledger.load([_signed(1, T0, section) for section in CONSOLE_SECTIONS])
        clock.now = T0 + 12 * DAY
        assert REGISTRY.get_sample_value("admin_access_review_age_days") == pytest.approx(12.0)
        clock.now = T0 + 101 * DAY
        assert REGISTRY.get_sample_value("admin_access_review_age_days") == pytest.approx(101.0)


# --- the API --------------------------------------------------------------------------


@pytest.fixture()
def keycloak() -> FakeKeycloak:
    return FakeKeycloak(datetime.now(UTC))


@pytest.fixture()
def openbao() -> FakeOpenBao:
    return FakeOpenBao()


@pytest.fixture()
def harness(tmp_path: Path, keycloak: FakeKeycloak, openbao: FakeOpenBao) -> Iterator[ApiHarness]:
    wiring = build_admin_wiring(
        identity=identity_wiring(keycloak, openbao), step_up=STEP_UP.service
    )
    yield from build_admin_harness(tmp_path, admin=wiring, signed_sections=())


def _review(harness: ApiHarness, role: str = "compliance_officer") -> dict[str, Any]:
    response = harness.client.get("/admin/access/review", headers=bearer(role))
    assert response.status_code == 200, response.text
    body: dict[str, Any] = response.json()
    return body


def _section(body: dict[str, Any], section: str) -> dict[str, Any]:
    return next(item for item in body["sections"] if item["section"] == section)


def _sign(harness: ApiHarness, role: str, section: str, digest: str) -> Any:
    return harness.client.post(
        "/admin/access/review/sign",
        json={"section": section, "review_digest": digest},
        headers=bearer(role),
    )


def _countersign(harness: ApiHarness, role: str, action_id: str) -> Any:
    """INT-563: through the step-up, the one way a second key is presented."""
    url = f"/admin/access/review/sign/{action_id}/countersign"
    return STEP_UP.approve(harness.client, url, action_id, role)


def _sign_and_countersign(
    harness: ApiHarness, section: str, countersigner: str, signer: str = "compliance_officer"
) -> Any:
    digest = _section(_review(harness), section)["review_digest"]
    opened = _sign(harness, signer, section, digest)
    assert opened.status_code == 200, opened.text
    return _countersign(harness, countersigner, opened.json()["action_id"])


class TestReviewRoute:
    def test_the_document_is_served_from_keycloak_and_the_chain(self, harness: ApiHarness) -> None:
        body = _review(harness)
        assert body["schema"] == "intake.admin.access_review.v1"
        assert body["policy"] == {
            "review_max_age_days": 100,
            "auto_disable_after_days": 60,
            "read_only_roles": ["platform_owner", "tenant_admin"],
        }
        assert body["status"]["never_reviewed"] is True
        assert body["status"]["read_only_roles"] == ["platform_owner", "tenant_admin"]
        subjects = {holder["subject"] for holder in body["holders"]}
        assert "kc-sub-platform-owner" in subjects and "kc-sub-no-staff-role" not in subjects
        # the requester's own read is on the chain, so it shows as their last action
        officer = next(h for h in body["holders"] if h["subject"] == "kc-sub-compliance-officer")
        assert officer["last_console_action_at"] is not None

    def test_no_name_mail_or_chain_material_reaches_the_document(self, harness: ApiHarness) -> None:
        text = harness.client.get("/admin/access/review", headers=bearer("compliance_officer")).text
        for forbidden in ("Synthetic", "invalid", "firstName", "email", "192.0.2.44"):
            assert forbidden not in text
        assert not HEX64.search(text)

    def test_a_tenant_reviewer_sees_only_their_own_clinician_section(
        self, harness: ApiHarness
    ) -> None:
        body = _review(harness, "tenant_clinical_responsible")
        assert [section["section"] for section in body["sections"]] == [CLINICIANS_A]
        assert {h["subject"] for h in body["holders"]} == set(
            _section(body, CLINICIANS_A)["holders"]
        )
        assert body["pending_offboardings"] == []

    def test_unconfigured_identity_answers_503(self, tmp_path: Path) -> None:
        for built in build_admin_harness(tmp_path):
            response = built.client.get(
                "/admin/access/review", headers=bearer("compliance_officer")
            )
            assert response.status_code == 503
            assert response.json()["error"] == "access_review_unconfigured"

    def test_an_unreachable_directory_is_503_not_an_empty_review(
        self, harness: ApiHarness, keycloak: FakeKeycloak
    ) -> None:
        keycloak.fail.add("users")
        response = harness.client.get("/admin/access/review", headers=bearer("compliance_officer"))
        assert response.status_code == 503
        assert response.json()["error"] == "directory_unavailable"


class TestSignAndCountersign:
    def test_the_ceremony_is_registered_as_two_keys_on_the_dangerous_direction(self) -> None:
        action = DANGEROUS_ACTIONS[ACCESS_REVIEW_SIGN.id]
        assert action.tier is ActionTier.T2
        assert action.direction is ActionDirection.DANGEROUS
        assert action.actor_roles == frozenset(
            {AdminRole.COMPLIANCE_OFFICER, AdminRole.TENANT_CLINICAL_RESPONSIBLE}
        )
        assert action.approver_roles == frozenset(
            {AdminRole.COMPLIANCE_OFFICER, AdminRole.QMS_OWNER}
        )
        assert action.runbook == "docs/runbooks/access-review.md"
        assert RUNBOOK.is_file()

    def test_a_countersigned_section_lands_on_the_chain_and_clears_its_age(
        self, harness: ApiHarness
    ) -> None:
        response = _sign_and_countersign(harness, SECTION_CONSOLE_ROLES, "qms_owner")
        assert response.status_code == 200, response.text
        assert response.json()["state"] == "signed"
        rows = [e for e in harness.audit_store.entries() if e.action == SIGNED_ACTION]
        assert len(rows) == 1
        assert rows[0].resource_ref.startswith(f"access_review:{SECTION_CONSOLE_ROLES}:")
        assert rows[0].actor == "kc-sub-qms-owner"
        section = _section(_review(harness), SECTION_CONSOLE_ROLES)
        assert section["last_signed_at"] is not None
        assert section["overdue"] is False

    def test_platform_owner_needs_a_countersignature_from_another_organisation(
        self, harness: ApiHarness
    ) -> None:
        same_org = _sign_and_countersign(harness, SECTION_PLATFORM_OWNER, "qms_owner")
        assert same_org.status_code == 409
        assert same_org.json()["error"] == "four_eyes_shared_organisation"
        external = _sign_and_countersign(harness, SECTION_PLATFORM_OWNER, "qms_owner_other_org")
        assert external.status_code == 200, external.text

    def test_both_console_sections_lift_the_read_only_downgrade(self, harness: ApiHarness) -> None:
        assert _review(harness)["status"]["read_only_roles"] == ["platform_owner", "tenant_admin"]
        assert _sign_and_countersign(harness, SECTION_CONSOLE_ROLES, "qms_owner").status_code == 200
        assert _review(harness)["status"]["read_only_roles"] == ["platform_owner", "tenant_admin"]
        assert (
            _sign_and_countersign(
                harness, SECTION_PLATFORM_OWNER, "qms_owner_other_org"
            ).status_code
            == 200
        )
        status = _review(harness)["status"]
        assert status["read_only_roles"] == []
        assert status["never_reviewed"] is False
        assert status["review_age_days"] == pytest.approx(0.0, abs=0.01)

    def test_a_digest_that_no_longer_matches_is_refused(self, harness: ApiHarness) -> None:
        response = _sign(harness, "compliance_officer", SECTION_CONSOLE_ROLES, "0" * 32)
        assert response.status_code == 409
        assert response.json()["error"] == "access_review_changed"

    def test_a_grant_between_sign_and_countersign_voids_the_signature(
        self, harness: ApiHarness, keycloak: FakeKeycloak
    ) -> None:
        digest = _section(_review(harness), SECTION_CONSOLE_ROLES)["review_digest"]
        opened = _sign(harness, "compliance_officer", SECTION_CONSOLE_ROLES, digest)
        assert opened.status_code == 200
        keycloak.roles["kc-sub-auditor"].append("sre_oncall")
        response = _countersign(harness, "qms_owner", opened.json()["action_id"])
        assert response.status_code == 409
        assert response.json()["error"] == "access_review_changed"
        assert not [e for e in harness.audit_store.entries() if e.action == SIGNED_ACTION]

    def test_the_signer_must_be_the_sections_reviewer(self, harness: ApiHarness) -> None:
        body = _review(harness)
        clinicians = _section(body, CLINICIANS_A)["review_digest"]
        refused = _sign(harness, "compliance_officer", CLINICIANS_A, clinicians)
        assert refused.status_code == 409
        assert refused.json()["error"] == "access_review_signer_ineligible"
        staff = _section(body, SECTION_CONSOLE_ROLES)["review_digest"]
        refused = _sign(harness, "tenant_clinical_responsible", SECTION_CONSOLE_ROLES, staff)
        assert refused.status_code == 409
        assert refused.json()["error"] == "access_review_signer_ineligible"
        assert (
            _sign(harness, "tenant_clinical_responsible", CLINICIANS_A, clinicians).status_code
            == 200
        )

    def test_an_unknown_section_is_refused(self, harness: ApiHarness) -> None:
        response = _sign(harness, "compliance_officer", "clinicians:tenant-z", "a" * 32)
        assert response.status_code == 409
        assert response.json()["error"] == "access_review_section_unknown"

    def test_nobody_countersigns_their_own_signature(self, harness: ApiHarness) -> None:
        response = _sign_and_countersign(harness, SECTION_CONSOLE_ROLES, "compliance_officer")
        assert response.status_code == 409
        assert response.json()["error"] == "four_eyes_self_approval"

    def test_a_step_up_is_spent_once_on_its_own_signature(self, harness: ApiHarness) -> None:
        body = _review(harness)
        first = _sign(
            harness,
            "compliance_officer",
            SECTION_CONSOLE_ROLES,
            _section(body, SECTION_CONSOLE_ROLES)["review_digest"],
        )
        second = _sign(
            harness,
            "compliance_officer",
            SECTION_PLATFORM_OWNER,
            _section(body, SECTION_PLATFORM_OWNER)["review_digest"],
        )
        # the external countersigner may countersign either section
        who = bearer("qms_owner_other_org")
        grant = STEP_UP.grant(harness.client, "qms_owner_other_org", second.json()["action_id"])
        assert grant.status_code == 200, grant.text
        body = {"step_up_grant": grant.json()["grant"]}
        first_url = f"/admin/access/review/sign/{first.json()['action_id']}/countersign"
        second_url = f"/admin/access/review/sign/{second.json()['action_id']}/countersign"
        # near miss: the grant presented for another signature is refused,
        # and is not burnt by the attempt
        crossed = harness.client.post(first_url, json=body, headers=who)
        assert (crossed.status_code, crossed.json()["error"]) == (403, "step_up_unknown")
        spent = harness.client.post(second_url, json=body, headers=who)
        assert spent.status_code == 200, spent.text
        reused = harness.client.post(second_url, json=body, headers=who)
        assert (reused.status_code, reused.json()["error"]) == (403, "step_up_unknown")


class TestReadOnlyEnforcedAtTheRoute:
    def _stale(self, tmp_path: Path, days: float) -> Iterator[ApiHarness]:
        signed_at = datetime.now(UTC)
        wiring = build_admin_wiring(review_clock=lambda: signed_at + timedelta(days=days))
        yield from build_admin_harness(tmp_path, admin=wiring, signed_at=signed_at)

    def _open_break_glass(self, harness: ApiHarness, role: str) -> Any:
        # platform_owner's claim carries no tenant; it is the one role that
        # may name one (files/08 §8 rule a), and break-glass needs one
        query = "?tenant=tenant-a" if role == "platform_owner" else ""
        return harness.client.post(
            f"/admin/break-glass{query}",
            json={
                "session_ref": "session:0f8a1c2d-4b5e-4a6f-9c31-2d4e6f8a1c2d",
                "reason_class": "patient_support_request",
                "justification": "Synthetic unit-lane support request for a missing record.",
                "controller_instruction_ref": "ci:tenant-a:2026-09-03:01",
            },
            headers=bearer(role),
        )

    def test_past_one_hundred_days_platform_owner_writes_are_refused_and_audited(
        self, tmp_path: Path
    ) -> None:
        for harness in self._stale(tmp_path, 100 + 1 / 86_400):
            before = len(harness.audit_store.entries())
            response = self._open_break_glass(harness, "platform_owner")
            assert response.status_code == 403
            assert response.json()["error"] == "access_review_overdue"
            appended = [e.action for e in harness.audit_store.entries()[before:]]
            assert appended == ["admin.break_glass.open.intent", "admin.break_glass.open.failure"]

    def test_reads_stay_open_to_a_downgraded_session(self, tmp_path: Path) -> None:
        for harness in self._stale(tmp_path, 150):
            assert (
                harness.client.get("/admin/whoami", headers=bearer("platform_owner")).status_code
                == 200
            )

    def test_other_roles_keep_writing(self, tmp_path: Path) -> None:
        for harness in self._stale(tmp_path, 150):
            assert self._open_break_glass(harness, "clinical_lead").status_code == 200

    def test_one_second_inside_the_threshold_still_writes(self, tmp_path: Path) -> None:
        for harness in self._stale(tmp_path, 100 - 1 / 86_400):
            assert self._open_break_glass(harness, "platform_owner").status_code == 200

    def test_a_countersigned_review_readmits_the_writes(
        self, tmp_path: Path, keycloak: FakeKeycloak, openbao: FakeOpenBao
    ) -> None:
        wiring = build_admin_wiring(
            identity=identity_wiring(keycloak, openbao), step_up=STEP_UP.service
        )
        for harness in build_admin_harness(tmp_path, admin=wiring, signed_sections=()):
            assert self._open_break_glass(harness, "platform_owner").status_code == 403
            # the reviewers are not downgraded, so a lapsed review can always be redone
            assert (
                _sign_and_countersign(harness, SECTION_CONSOLE_ROLES, "qms_owner").status_code
                == 200
            )
            assert self._open_break_glass(harness, "platform_owner").status_code == 403
            assert (
                _sign_and_countersign(
                    harness, SECTION_PLATFORM_OWNER, "qms_owner_other_org"
                ).status_code
                == 200
            )
            assert self._open_break_glass(harness, "platform_owner").status_code == 200

    def test_the_harness_seed_is_what_keeps_other_suites_writable(self, tmp_path: Path) -> None:
        for harness in build_admin_harness(tmp_path, signed_sections=()):
            assert self._open_break_glass(harness, "platform_owner").status_code == 403
        seeded = tmp_path / "seeded"
        seeded.mkdir()
        for harness in build_admin_harness(seeded):
            assert self._open_break_glass(harness, "platform_owner").status_code == 200


# --- the signal ------------------------------------------------------------------------


class TestSignal:
    def test_the_gauge_is_catalogued_live(self) -> None:
        catalog = load_metrics_catalog(CATALOG)
        entry = next(m for m in catalog.metrics if m.name == "admin_access_review_age_days")
        assert entry.status == "live"
        assert entry.type == "gauge"
        assert entry.labels == []

    def test_an_alert_pages_above_one_hundred_days_and_links_the_runbook(self) -> None:
        rules = yaml.safe_load(RULES.read_text(encoding="utf-8"))
        alerts = {rule["alert"]: rule for group in rules["groups"] for rule in group["rules"]}
        rule = alerts["AccessReviewOverdue"]
        assert "admin_access_review_age_days" in rule["expr"]
        assert "> 100" in rule["expr"]
        assert rule["labels"]["severity"] == "page"
        assert load_metrics_catalog(CATALOG).unknown_references(str(rule["expr"])) == frozenset()
        runbook, _, anchor = str(rule["annotations"]["runbook"]).partition("#")
        assert runbook == "docs/runbooks/access-review.md"
        assert f"\n### {anchor}\n" in (REPO / runbook).read_text(encoding="utf-8").lower()


# --- the e2e fixtures are the route's own view ------------------------------------------


def _recorder() -> ModuleType:
    path = REPO / "scripts" / "dev" / "record_access_fixture.py"
    spec = importlib.util.spec_from_file_location("record_access_fixture", path)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


class TestFixturesAreRecordedFromTheRoute:
    @pytest.mark.parametrize(
        ("name", "reviewed"),
        [("access.payload.json", True), ("access.lapsed.payload.json", False)],
    )
    def test_the_committed_fixture(self, name: str, reviewed: bool) -> None:
        recorded = json.loads((E2E / name).read_text(encoding="utf-8"))
        assert recorded == _recorder().record(reviewed=reviewed), (
            f"apps/admin-web/e2e/fixtures/{name} drifted from the review view; re-run "
            "uv run python scripts/dev/record_access_fixture.py"
        )
